/* @autogenerated */
package net.civeira.phylax.features.oauth.tokensecurity.application;

import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.util.Base64;
import java.util.List;
import java.util.Optional;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import jakarta.enterprise.context.ApplicationScoped;
import net.civeira.phylax.features.oauth.client.domain.ClientDetails;

/**
 * The {@code sub} a relying party sees (OIDC Core §8, task 4.4).
 *
 * <p>
 * A public client gets the username. A pairwise client gets
 * {@code HMAC-SHA256(oidc.pairwise.salt, sector | username)}: stable for the user and the sector,
 * different between sectors and not reversible. The sector is the host of the registered
 * {@code sector_identifier_uri} or, without one, the single host of its redirect URIs. The same
 * value goes to the ID token, UserInfo and the logout token; access and refresh tokens keep the
 * username, which only this server reads. A pairwise client without sector, or a server without
 * salt, cannot get a subject (fail closed).
 */
@ApplicationScoped
public class SubjectResolver {

  private final Optional<String> salt;

  public SubjectResolver(@ConfigProperty(name = "oidc.pairwise.salt") Optional<String> salt) {
    this.salt = salt.filter(s -> !s.isBlank());
  }

  /**
   * Subject of a user for a client.
   *
   * @param client relying party
   * @param username local subject
   * @return the subject to put in the RP-facing artifacts
   * @throws IllegalStateException for a pairwise client without sector or without salt
   */
  public String subject(ClientDetails client, String username) {
    return subject(client.isPairwiseSubject(), client.getSectorIdentifierUri(),
        client.getAllowedRedirectUris(), username);
  }

  /**
   * Subject of a user for a client described by its registered values.
   *
   * @param pairwise whether the client registered {@code subject_type=pairwise}
   * @param sectorIdentifierUri registered sector URI, may be null
   * @param redirects registered redirect URIs
   * @param username local subject
   * @return the subject
   */
  public String subject(boolean pairwise, String sectorIdentifierUri, List<String> redirects,
      String username) {
    if (!pairwise || username == null) {
      return username;
    }
    String sector = sector(sectorIdentifierUri, redirects).orElseThrow(
        () -> new IllegalStateException("A pairwise client needs a single sector host"));
    String key = salt.orElseThrow(
        () -> new IllegalStateException("oidc.pairwise.salt is required for pairwise clients"));
    try {
      Mac mac = Mac.getInstance("HmacSHA256");
      mac.init(new SecretKeySpec(key.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
      byte[] digest = mac.doFinal((sector + "|" + username).getBytes(StandardCharsets.UTF_8));
      return Base64.getUrlEncoder().withoutPadding().encodeToString(digest);
    } catch (GeneralSecurityException ex) {
      throw new IllegalStateException("HMAC-SHA256 is unavailable", ex);
    }
  }

  /**
   * Whether pairwise subjects can be issued at all (the salt is configured).
   *
   * @return true when configured
   */
  public boolean pairwiseAvailable() {
    return salt.isPresent();
  }

  static Optional<String> sector(String sectorIdentifierUri, List<String> redirects) {
    if (sectorIdentifierUri != null && !sectorIdentifierUri.isBlank()) {
      return host(sectorIdentifierUri);
    }
    List<String> hosts = redirects == null ? List.of()
        : redirects.stream().map(SubjectResolver::host).flatMap(Optional::stream).distinct()
            .toList();
    return hosts.size() == 1 ? Optional.of(hosts.get(0)) : Optional.empty();
  }

  private static Optional<String> host(String uri) {
    try {
      return Optional.ofNullable(URI.create(uri).getHost()).map(h -> h.toLowerCase());
    } catch (IllegalArgumentException ex) {
      return Optional.empty();
    }
  }
}
